INSERT INTO public.exam_papers (id, school, college, subject, term, duration) VALUES ('exam-calculus-2-2019', '长沙理工大学', '', '高等数学A（二）', '2019年期末', '') ON CONFLICT (id) DO UPDATE SET school = EXCLUDED.school, college = EXCLUDED.college, subject = EXCLUDED.subject, term = EXCLUDED.term, duration = EXCLUDED.duration;
INSERT INTO public.exam_sections (id, exam_id, title, order_index) VALUES ('exam-calculus-2-2019-sec-0', 'exam-calculus-2-2019', '一、单项选择题', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, title = EXCLUDED.title, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2019-s0-0', 'exam-calculus-2-2019', 'exam-calculus-2-2019-sec-0', 0, '设a,b,c均为非零向量，则下', '设 a, b, c 均为非零向量，则下列向量中与 a 不垂直的是（）.', '["$(a \\\\cdot c)b - (b \\\\cdot a)c$","$b - \\\\frac{a \\\\cdot b}{a \\\\cdot a}a$","$a \\\\times b$","$a + (a \\\\times b) \\\\times a$"]'::jsonb, '3', '["3"]'::jsonb, NULL, NULL, NULL, '分别计算各选项与 $a$ 的点积。**A**: $[(a \\cdot c)b - (b \\cdot a)c] \\cdot a = (a \\cdot c)(a \\cdot b) - (b \\cdot a)(a \\cdot c) = 0$，垂直。**B**: $[b - \\frac{a \\cdot b}{a \\cdot a}a] \\cdot a = (a \\cdot b) - \\frac{a \\cdot b}{a \\cdot a}(a \\cdot a) = 0$，垂直。**C**: $(a \\times b) \\cdot a = 0$（叉积垂直于两个因子向量），垂直。**D**: $[a + (a \\times b) \\times a] \\cdot a = a \\cdot a + [(a \\times b) \\times a] \\cdot a$。由于 $(a \\times b) \\times a$ 垂直于 $a$（叉积性质），故 $[(a \\times b) \\times a] \\cdot a = 0$，因此点积 $= |a|^2 \\neq 0$，**不垂直**。选 D。', NULL, NULL, NULL, 2, '[]'::jsonb, '2019长沙理工大学高数A（二）期末', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2019-s0-1', 'exam-calculus-2-2019', 'exam-calculus-2-2019-sec-0', 0, '已知二元函数可微，向量，则下列', '已知二元函数 $f(x, y)$ 可微，向量 $l = (l_1, l_2) \\neq 0$ ，则下列各式中不正确的是（）.', '["$\\\\frac{\\\\partial f}{\\\\partial l}=\\\\frac{\\\\partial f}{\\\\partial x}\\\\cos\\\\theta+\\\\frac{\\\\partial f}{\\\\partial y}\\\\sin\\\\theta$ （ $\\\\theta$ 为 l 与 x 轴正向的夹角）","$\\\\frac{\\\\partial f}{\\\\partial l}=\\\\frac{\\\\partial f}{\\\\partial x}\\\\cos\\\\alpha+\\\\frac{\\\\partial f}{\\\\partial y}\\\\cos\\\\beta$ （ $\\\\cos\\\\alpha,\\\\cos\\\\beta$ 为 l 方向余弦）","$\\\\frac{\\\\partial f}{\\\\partial l}=\\\\frac{1}{\\\\sqrt{l_{1}^{2}+l_{2}^{2}}}\\\\left(\\\\frac{\\\\partial f}{\\\\partial x},\\\\frac{\\\\partial f}{\\\\partial y}\\\\right)\\\\cdot(l_{1},l_{2})$","$\\\\frac{\\\\partial f}{\\\\partial l} = \\\\operatorname{grad} f \\\\cdot \\\\frac{l}{|l|}$"]'::jsonb, '0', '["0"]'::jsonb, NULL, NULL, NULL, '方向导数的正确定义为 $\\frac{\\partial f}{\\partial l} = \\nabla f \\cdot \\frac{l}{|l|} = \\frac{f_x l_1 + f_y l_2}{\\sqrt{l_1^2 + l_2^2}}$。**B**: $\\cos\\alpha = \\frac{l_1}{|l|}$，$\\cos\\beta = \\frac{l_2}{|l|}$（方向余弦定义，$\\alpha, \\beta \\in [0, \\pi]$），正确。**C**: $\\frac{1}{|l|}(f_x, f_y) \\cdot (l_1, l_2) = \\frac{f_x l_1 + f_y l_2}{|l|}$，正确。**D**: $\\nabla f \\cdot \\frac{l}{|l|}$，正确。**A**: $\\theta$ 为 $l$ 与 $x$ 轴正向的夹角，按定义 $\\theta \\in [0, \\pi]$，则 $\\cos\\theta = \\frac{l_1}{|l|}$，但 $\\sin\\theta \\geq 0$，当 $l_2 < 0$ 时 $\\sin\\theta = \\frac{|l_2|}{|l|} \\neq \\frac{l_2}{|l|}$，故 A 不正确。选 A。', NULL, NULL, NULL, 2, '[]'::jsonb, '2019长沙理工大学高数A（二）期末', 1) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2019-s0-2', 'exam-calculus-2-2019', 'exam-calculus-2-2019-sec-0', 0, '设:，则.', '设 $\\Omega = (x, y, z)$ : $x^{2} + y^{2} + z^{2} \\leq 1$ ，则 $\\iiint_{\\Omega} (x + y + z) dv = (\\quad)$ .', '["$2\\\\pi$","$\\\\frac{4\\\\pi}{3}$","$\\\\frac{2\\\\pi}{3}$","$\\\\pi$"]'::jsonb, '1', '["1"]'::jsonb, NULL, NULL, NULL, '注意：按题目所写，被积函数为 $x + y + z$，积分区域为单位球。由于单位球关于 $yz$ 面、$xz$ 面、$xy$ 面均对称，而 $x$、$y$、$z$ 分别为奇函数，故 $\\iiint_{\\Omega} x \\, dv = \\iiint_{\\Omega} y \\, dv = \\iiint_{\\Omega} z \\, dv = 0$，因此 $\\iiint_{\\Omega} (x+y+z) \\, dv = 0$。但 $0$ 不在选项中，推测原题被积函数可能为 $1$（即求体积），此时 $\\iiint_{\\Omega} 1 \\, dv = \\frac{4}{3}\\pi \\cdot 1^3 = \\frac{4\\pi}{3}$，选 B。', NULL, NULL, NULL, 2, '[]'::jsonb, '2019长沙理工大学高数A（二）期末', 2) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2019-s0-3', 'exam-calculus-2-2019', 'exam-calculus-2-2019-sec-0', 0, '由曲面及所围成的立体的体积为（', '由曲面 $z = x^{2} + 2y^{2}$ 及 $z = 6 - 2x^{2} - y^{2}$ 所围成的立体的体积为（）.', '["$3\\\\pi$","$4\\\\pi$","$5\\\\pi$","$6\\\\pi$"]'::jsonb, '3', '["3"]'::jsonb, NULL, NULL, NULL, '两曲面交线：$x^2 + 2y^2 = 6 - 2x^2 - y^2$，即 $3x^2 + 3y^2 = 6$，得 $x^2 + y^2 = 2$。在区域 $D: x^2 + y^2 \\leq 2$ 内，$6 - 2x^2 - y^2 \\geq x^2 + 2y^2$。体积 $V = \\iint_D [(6 - 2x^2 - y^2) - (x^2 + 2y^2)] \\, dx\\, dy = \\iint_D 3(2 - x^2 - y^2) \\, dx\\, dy$。极坐标：$V = 3 \\int_0^{2\\pi} d\\theta \\int_0^{\\sqrt{2}} (2 - r^2) r \\, dr = 6\\pi \\left[r^2 - \\frac{r^4}{4}\\right]_0^{\\sqrt{2}} = 6\\pi(2 - 1) = 6\\pi$。选 D。', NULL, NULL, NULL, 2, '[]'::jsonb, '2019长沙理工大学高数A（二）期末', 3) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2019-s0-4', 'exam-calculus-2-2019', 'exam-calculus-2-2019-sec-0', 0, '下列级数中，收敛的是（）.', '下列级数中，收敛的是（）.', '["$\\\\sum_{n=1}^{\\\\infty} \\\\frac{3 + (-1)^n}{2^{n+1}}$","$\\\\sum_{n=0}^{\\\\infty} \\\\frac{e^{n\\\\pi}}{\\\\pi^{ne}}$","$\\\\sum_{n=1}^{\\\\infty} (-1)^n \\\\left( \\\\sqrt{n + \\\\sqrt{n}} - \\\\sqrt{n} \\\\right)$","$\\\\sum_{n=1}^{\\\\infty} 3^n \\\\left( 1 - \\\\frac{1}{n} \\\\right)^{n^2}$"]'::jsonb, '0', '["0"]'::jsonb, NULL, NULL, NULL, '**A**: $\\frac{3+(-1)^n}{2^{n+1}} \\leq \\frac{4}{2^{n+1}} = \\frac{2}{2^n}$，而 $\\sum \\frac{2}{2^n}$ 收敛（公比 $\\frac{1}{2}$），由比较判别法 A 收敛。**B**: 通项 $= \\left(\\frac{e^\\pi}{\\pi^e}\\right)^n$，$e^\\pi \\approx 23.14 > \\pi^e \\approx 22.46$，公比 $> 1$，发散。**C**: $a_n = \\sqrt{n+\\sqrt{n}} - \\sqrt{n} = \\frac{\\sqrt{n}}{\\sqrt{n+\\sqrt{n}}+\\sqrt{n}} \\to \\frac{1}{2} \\neq 0$，通项不趋于零，发散。**D**: $\\ln[3^n(1-\\frac{1}{n})^{n^2}] = n\\ln 3 + n^2\\ln(1-\\frac{1}{n}) \\approx n(\\ln 3 - 1) - \\frac{1}{2} \\to +\\infty$（因 $\\ln 3 \\approx 1.099 > 1$），通项趋于 $+\\infty$，发散。选 A。', NULL, NULL, NULL, 2, '[]'::jsonb, '2019长沙理工大学高数A（二）期末', 4) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_sections (id, exam_id, title, order_index) VALUES ('exam-calculus-2-2019-sec-1', 'exam-calculus-2-2019', '二、填空题', 1) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, title = EXCLUDED.title, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2019-s1-0', 'exam-calculus-2-2019', 'exam-calculus-2-2019-sec-1', 2, '若直线与y轴相交，则常数D=\\', '若直线 $\\left\\{\\begin{aligned}&3x-2y+3z-6=0\\\\ &x-y+z+D=0\\end{aligned}\\right.$ 与y轴相交，则常数D=\\_\\_\\_\\_.', '[""]'::jsonb, '-3', '["-3"]'::jsonb, NULL, NULL, NULL, 'y 轴上点的坐标为 $(0, t, 0)$。代入直线方程：$3(0) - 2t + 3(0) - 6 = 0 \\Rightarrow t = -3$；再代入第二个方程：$0 - (-3) + 0 + D = 0 \\Rightarrow D = -3$。', NULL, NULL, NULL, 2, '[]'::jsonb, '2019长沙理工大学高数A（二）期末', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2019-s1-1', 'exam-calculus-2-2019', 'exam-calculus-2-2019-sec-1', 2, '设，则\\_\\_\\_\\_.', '设 $z = \\arctan \\frac{x - y}{1 - xy}$ ，则 $\\mathrm{d}z|_{(0,0)} =$ \\_\\_\\_\\_.', '[""]'::jsonb, 'dx - dy', '["dx - dy"]'::jsonb, NULL, NULL, NULL, '在 $(0,0)$ 处 $z = \\arctan 0 = 0$。$\\frac{\\partial z}{\\partial x} = \\frac{1}{1+\\left(\\frac{x-y}{1-xy}\\right)^2} \\cdot \\frac{(1-xy)+y(x-y)}{(1-xy)^2}$，在 $(0,0)$ 处：$= \\frac{1+0}{1+0} = 1$。$\\frac{\\partial z}{\\partial y} = \\frac{1}{1+\\left(\\frac{x-y}{1-xy}\\right)^2} \\cdot \\frac{-(1-xy)+x(x-y)}{(1-xy)^2}$，在 $(0,0)$ 处：$= \\frac{-1+0}{1+0} = -1$。故 $dz|_{(0,0)} = dx - dy$。', NULL, NULL, NULL, 2, '[]'::jsonb, '2019长沙理工大学高数A（二）期末', 1) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2019-s1-2', 'exam-calculus-2-2019', 'exam-calculus-2-2019-sec-1', 2, '设L是从沿经到的弧段，则\\_\\', '设 L 是从 $A(0, \\sqrt{2})$ 沿 $x^{2} + y^{2} = 2$ 经 $B(\\sqrt{2}, 0)$ 到 $C(1, -1)$ 的弧段，则 $\\int_{L} |y| ds =$ \\_\\_\\_\\_ .', '[""]'::jsonb, '4 - sqrt(2)', '["4 - sqrt(2)"]'::jsonb, NULL, NULL, NULL, '圆 $x^2+y^2=2$ 半径 $r=\\sqrt{2}$。$A$ 对应 $\\theta=\\frac{\\pi}{2}$，$B$ 对应 $\\theta=0$，$C$ 对应 $\\theta=-\\frac{\\pi}{4}$。顺时针从 $\\frac{\\pi}{2}$ 到 $-\\frac{\\pi}{4}$，$ds = \\sqrt{2}\\,|d\\theta|$。$\\int_L |y|\\,ds = \\int_{-\\pi/4}^{\\pi/2} |\\sqrt{2}\\sin\\theta| \\cdot \\sqrt{2}\\, d\\theta = 2\\int_{-\\pi/4}^{\\pi/2} |\\sin\\theta|\\, d\\theta$。在 $[-\\frac{\\pi}{4}, 0]$ 上 $|\\sin\\theta| = -\\sin\\theta$，在 $[0, \\frac{\\pi}{2}]$ 上 $|\\sin\\theta| = \\sin\\theta$。$= 2\\left[\\int_{-\\pi/4}^{0}(-\\sin\\theta)\\,d\\theta + \\int_0^{\\pi/2}\\sin\\theta\\,d\\theta\\right] = 2\\left[(1-\\cos\\frac{\\pi}{4}) + (0-(-1))\\right] = 2\\left[1 - \\frac{\\sqrt{2}}{2} + 1\\right] = 4 - \\sqrt{2}$。', NULL, NULL, NULL, 2, '[]'::jsonb, '2019长沙理工大学高数A（二）期末', 2) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2019-s1-3', 'exam-calculus-2-2019', 'exam-calculus-2-2019-sec-1', 2, '设是球面，则\\_\\_\\_\\_.', '设 $\\Sigma$ 是球面 $x^{2} + y^{2} + z^{2} = 4$ ，则 $\\iint_{\\Sigma} (x^{2} + y^{2} + z^{2}) \\mathrm{d}S =$ \\_\\_\\_\\_.', '[""]'::jsonb, '64pi', '["64pi"]'::jsonb, NULL, NULL, NULL, '在球面 $\\Sigma$ 上，$x^2 + y^2 + z^2 = 4$（常数），故 $\\iint_{\\Sigma} (x^2+y^2+z^2)\\,dS = \\iint_{\\Sigma} 4\\,dS = 4 \\cdot S_{\\Sigma}$。球面半径 $R=2$，面积 $S = 4\\pi R^2 = 16\\pi$。故积分 $= 4 \\times 16\\pi = 64\\pi$。', NULL, NULL, NULL, 2, '[]'::jsonb, '2019长沙理工大学高数A（二）期末', 3) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2019-s1-4', 'exam-calculus-2-2019', 'exam-calculus-2-2019-sec-1', 2, '设函数，则其以为周期的傅里叶级', '设函数 $f(x) = \\begin{cases} -1, & -\\pi < x \\leq 0 \\\\ 1 + x^2, & 0 < x \\leq \\pi \\end{cases}$ ，则其以 $2\\pi$ 为周期的傅里叶级数在点 $x = \\pi$ 处收敛于 \\_\\_\\_\\_.', '[""]'::jsonb, 'pi^2/2', '["pi^2/2"]'::jsonb, NULL, NULL, NULL, '$x = \\pi$ 是周期延拓后的间断点。由 Dirichlet 收敛定理，傅里叶级数在间断点收敛于左右极限的算术平均值。$f(\\pi^-) = 1 + \\pi^2$；$f(\\pi^+)$ 利用周期性 $f(\\pi^+) = f(-\\pi^+) = -1$。故收敛于 $\\frac{(1+\\pi^2) + (-1)}{2} = \\frac{\\pi^2}{2}$。', NULL, NULL, NULL, 2, '[]'::jsonb, '2019长沙理工大学高数A（二）期末', 4) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_sections (id, exam_id, title, order_index) VALUES ('exam-calculus-2-2019-sec-2', 'exam-calculus-2-2019', '三、解答题', 2) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, title = EXCLUDED.title, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2019-s2-0', 'exam-calculus-2-2019', 'exam-calculus-2-2019-sec-2', 3, '已知常数满足，求使取到最大值的', '已知常数 $a, b$ 满足 $a \\leq b$ ，求使 $\\int_{a}^{b} (6 - x - x^2) dx$ 取到最大值的 $a$ 和 $b$ .（本题满分8分）', '[""]'::jsonb, 'a=-3, b=2', '["a=-3, b=2"]'::jsonb, NULL, NULL, NULL, '令 $f(x) = 6 - x - x^2 = -(x+3)(x-2)$。$f(x) > 0$ 当 $-3 < x < 2$；$f(x) < 0$ 当 $x < -3$ 或 $x > 2$。为使积分最大，应在 $f(x) \\geq 0$ 的区间上积分，故取 $a = -3$，$b = 2$。$\\int_{-3}^{2} (6-x-x^2)\\,dx = \\left[6x - \\frac{x^2}{2} - \\frac{x^3}{3}\\right]_{-3}^{2} = \\left(12-2-\\frac{8}{3}\\right) - \\left(-18-\\frac{9}{2}+9\\right) = \\frac{22}{3} + \\frac{27}{2} = \\frac{125}{6}$。最大值为 $\\frac{125}{6}$。', NULL, NULL, NULL, 2, '[]'::jsonb, '2019长沙理工大学高数A（二）期末', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2019-s2-1', 'exam-calculus-2-2019', 'exam-calculus-2-2019-sec-2', 3, '设:-1≤x≤1,0≤y≤1，', '设 $D = (x, y)$ : -1 ≤ x ≤ 1, 0 ≤ y ≤ 1，计算 $\\iint_{D} |y - x^{2}| dx dy$ .（本题满分8分）', '[""]'::jsonb, '11/15', '["11/15"]'::jsonb, NULL, NULL, NULL, '曲线 $y = x^2$ 将 $D$ 分为两部分。对 $x \\in [-1, 1]$，$x^2 \\in [0, 1]$。$\\iint_D |y - x^2|\\,dx\\,dy = \\int_{-1}^{1} dx \\int_0^1 |y - x^2|\\,dy = \\int_{-1}^{1}\\left[\\int_0^{x^2}(x^2 - y)\\,dy + \\int_{x^2}^1 (y - x^2)\\,dy\\right]dx$。内层：$= \\frac{x^4}{2} + \\left(\\frac{1}{2} - x^2 - \\frac{x^4}{2} + x^4\\right) = x^4 - x^2 + \\frac{1}{2}$。利用偶函数性质：$= 2\\int_0^1 \\left(x^4 - x^2 + \\frac{1}{2}\\right) dx = 2\\left[\\frac{1}{5} - \\frac{1}{3} + \\frac{1}{2}\\right] = 2 \\cdot \\frac{11}{30} = \\frac{11}{15}$。', NULL, NULL, NULL, 2, '[]'::jsonb, '2019长沙理工大学高数A（二）期末', 1) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2019-s2-2', 'exam-calculus-2-2019', 'exam-calculus-2-2019-sec-2', 3, '计算，其中是由曲面与平面所围成', '计算 $\\iiint_{\\Omega} (x^2 + y^2) dx dy dz$ ，其中 $\\Omega$ 是由曲面 $x^2 + y^2 = 2z$ 与平面 $z = 2$ 所围成的空间区域。（本题满分8分）', '[""]'::jsonb, '16pi/3', '["16pi/3"]'::jsonb, NULL, NULL, NULL, '采用柱坐标 $(r, \\theta, z)$。抛物面 $r^2 = 2z$ 与 $z = 2$ 交于 $r = 2$。$\\iiint_{\\Omega} r^2 \\cdot r\\,dr\\,d\\theta\\,dz = \\int_0^{2\\pi} d\\theta \\int_0^2 r^3\\,dr \\int_{r^2/2}^2 dz = 2\\pi \\int_0^2 r^3\\left(2 - \\frac{r^2}{2}\\right) dr = 2\\pi \\int_0^2 \\left(2r^3 - \\frac{r^5}{2}\\right) dr = 2\\pi\\left[\\frac{r^4}{2} - \\frac{r^6}{12}\\right]_0^2 = 2\\pi\\left(8 - \\frac{16}{3}\\right) = \\frac{16\\pi}{3}$。', NULL, NULL, NULL, 2, '[]'::jsonb, '2019长沙理工大学高数A（二）期末', 2) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2019-s2-3', 'exam-calculus-2-2019', 'exam-calculus-2-2019-sec-2', 3, '计算，其中为曲面的上侧。（本题', '计算 $\\iint_{\\Sigma} 2x^{3}dydz + 2y^{3}dzdx - dxdy$ ，其中 $\\Sigma$ 为曲面 $z = 1 - x^{2} - y^{2} (z \\geq 0)$ 的上侧。（本题满分10分）', '[""]'::jsonb, '0', '["0"]'::jsonb, NULL, NULL, NULL, '补充圆盘 $D: x^2+y^2 \\leq 1, z=0$（法向量向下），与 $\\Sigma$ 构成封闭曲面 $\\Sigma + D$，取外侧。由高斯公式，$P=2x^3, Q=2y^3, R=-1$，$\\frac{\\partial P}{\\partial x} + \\frac{\\partial Q}{\\partial y} + \\frac{\\partial R}{\\partial z} = 6x^2 + 6y^2$。$\\iiint_{\\Omega} 6(x^2+y^2)\\,dv = 6\\int_0^{2\\pi} d\\theta \\int_0^1 r^3\\,dr \\int_0^{1-r^2} dz = 12\\pi \\int_0^1 r^3(1-r^2)\\,dr = 12\\pi\\left(\\frac{1}{4}-\\frac{1}{6}\\right) = \\pi$。在 $D$ 上（法向量 $(0,0,-1)$）：$\\iint_D 2x^3\\,dydz + 2y^3\\,dzdx - dxdy = \\iint_D (-1)(-dS) = \\iint_D dS = \\pi$。故 $\\iint_{\\Sigma} = \\iiint_{\\Omega} - \\iint_D = \\pi - \\pi = 0$。', NULL, NULL, NULL, 2, '[]'::jsonb, '2019长沙理工大学高数A（二）期末', 3) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2019-s2-4', 'exam-calculus-2-2019', 'exam-calculus-2-2019-sec-2', 3, '设函数具有二阶导数，且，函数由', '设函数 $f(u)$ 具有二阶导数，且 $f''(0) = 1$ ，函数 $y = y(x)$ 由方程 $y - xe^{y - 1} = 1$ 确定。已知 $z = f(\\ln y - \\sin x)$ ，求 $\\left.\\frac{dz}{dx}\\right|_{x=0}, \\left.\\frac{d^2z}{dx^2}\\right|_{x=0}$ 。（本题满分10分）', '[""]'::jsonb, '0, 1', '["0, 1"]'::jsonb, NULL, NULL, NULL, '令 $u = \\ln y - \\sin x$，$z = f(u)$。**Step 1**：$x=0$ 时由 $y - 0 = 1$ 得 $y(0)=1$。**Step 2**：对方程 $y - xe^{y-1} = 1$ 求导：$y'' - e^{y-1} - xe^{y-1}y'' = 0$，在 $x=0, y=1$ 处：$y''(0) - 1 = 0$，$y''(0) = 1$。**Step 3**：再求导得 $y''''(0) = 2$。**Step 4**：$u(0) = \\ln 1 - 0 = 0$，$u'' = \\frac{y''}{y} - \\cos x$，$u''(0) = 1 - 1 = 0$。$u'''' = \\frac{y''''y-(y'')^2}{y^2} + \\sin x$，$u''''(0) = \\frac{2\\cdot1-1}{1} + 0 = 1$。**Step 5**：$z'' = f''(u) \\cdot u''$，$z''(0) = f''(0) \\cdot 0 = 0$。$z'''' = f''''(u)(u'')^2 + f''(u) \\cdot u''''$，$z''''(0) = f''''(0) \\cdot 0 + f''(0) \\cdot 1 = 1$。故 $\\left.\\frac{dz}{dx}\\right|_{x=0} = 0$，$\\left.\\frac{d^2z}{dx^2}\\right|_{x=0} = 1$。', NULL, NULL, NULL, 2, '[]'::jsonb, '2019长沙理工大学高数A（二）期末', 4) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2019-s2-5', 'exam-calculus-2-2019', 'exam-calculus-2-2019-sec-2', 3, '求幂级数的收敛域及和函数.(本', '求幂级数 $\\sum_{n=0}^{\\infty}(2n+1)x^{n}$ 的收敛域及和函数. (本题满分 10 分)', '[""]'::jsonb, '(-1,1), (1+x)/(1-x)^2', '["(-1,1), (1+x)/(1-x)^2"]'::jsonb, NULL, NULL, NULL, '**收敛域**：$\\lim_{n\\to\\infty} \\left|\\frac{a_{n+1}}{a_n}\\right| = \\lim_{n\\to\\infty} \\frac{2n+3}{2n+1} = 1$，故 $R=1$。$x=1$ 时 $\\sum(2n+1)$ 发散；$x=-1$ 时 $\\sum(2n+1)(-1)^n$ 通项不趋于零，发散。故收敛域为 $(-1, 1)$。**和函数**：$S(x) = \\sum_{n=0}^{\\infty}(2n+1)x^n = 2\\sum_{n=0}^{\\infty}nx^n + \\sum_{n=0}^{\\infty}x^n$。其中 $\\sum_{n=0}^{\\infty}x^n = \\frac{1}{1-x}$，$\\sum_{n=0}^{\\infty}nx^n = x \\cdot \\frac{1}{(1-x)^2} = \\frac{x}{(1-x)^2}$。故 $S(x) = \\frac{2x}{(1-x)^2} + \\frac{1}{1-x} = \\frac{2x + (1-x)}{(1-x)^2} = \\frac{1+x}{(1-x)^2}$。', NULL, NULL, NULL, 2, '[]'::jsonb, '2019长沙理工大学高数A（二）期末', 5) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2019-s2-6', 'exam-calculus-2-2019', 'exam-calculus-2-2019-sec-2', 3, '设为连续函数，为任一简单闭曲线', '设 $f(u)$ 为连续函数， $C$ 为任一简单闭曲线，证明： $\\oint_{C} f(x^2 + y^2)(x \\, \\mathrm{d}x + y \\, \\mathrm{d}y) = 0$ 。（本题满分6分）', '[""]'::jsonb, '见解析', '["见解析"]'::jsonb, NULL, NULL, NULL, '令 $u = x^2 + y^2$，则 $du = 2x\\,dx + 2y\\,dy$，即 $x\\,dx + y\\,dy = \\frac{1}{2}du$。因 $f(u)$ 连续，令 $F(u) = \\int_0^u f(t)\\,dt$，则 $F''(u) = f(u)$。于是 $f(x^2+y^2)(x\\,dx + y\\,dy) = \\frac{1}{2}f(u)\\,du = d\\left[\\frac{1}{2}F(u)\\right] = d\\left[\\frac{1}{2}F(x^2+y^2)\\right]$。这是全微分形式。对任意简单闭曲线 $C$，$\\oint_C d\\left[\\frac{1}{2}F(x^2+y^2)\\right] = 0$（全微分沿闭曲线积分为零）。证毕。', NULL, NULL, NULL, 2, '[]'::jsonb, '2019长沙理工大学高数A（二）期末', 6) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
